-- club-refrigeration-c-c-rosslyn (researched)
UPDATE businesses SET description = 'Club Refrigeration CC has operated since 1976 as South Africa''s leading cleanroom manufacturer, running from a fully owned 10,000 square metre site in Rosslyn, Pretoria, with a long-serving, well-trained permanent workforce backed by qualified sub-contractors. The company offers full turnkey services for industrial-scale projects, from design and specialist engineering through manufacture, installation and ongoing repairs and maintenance, covering cleanrooms and GMP facilities, air handling units, fire-rated panels and doors, cannabis processing plants, post-harvest cooling, and mortuaries.

An active research and development programme has produced several products later copied across the industry, including its tongue-and-groove panel jointing system, flashing profiles and extrusions, and sliding door hardware. Club Refrigeration positions its approach around thorough consultation to identify each customer''s specific needs before offering an economically viable solution, serving pharmaceutical, agricultural and food industry clients who need controlled environments built to a precise specification rather than off-the-shelf.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.clubref.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'club-refrigeration-c-c-rosslyn' AND description = 'Club Refrigeration CC is a South African manufacturer specializing in cleanroom design and construction, operating from a facility in Rosslyn, Pretoria. It provides turnkey services from design and engineering to manufacture, installation, repairs and maintenance, covering cleanrooms and GMP facilities, air handling units, fire-rated panels and doors, cannabis processing plants, post-harvest cooling, and mortuaries, serving pharmaceutical, agricultural, and food industry clients.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
