UPDATE businesses SET description = 'S and P Power Units has more than 30 years of experience in renewable energy and power supply, having installed over 7,500 systems across Southern Africa, Sub-Saharan Africa and Eastern Africa. The company designs, supplies and installs off-grid and grid-tied solar and backup power solutions for commercial, residential and agricultural clients, tailoring each system to the client''s specific power needs rather than offering a single standard setup.

Alongside full system installation, S and P Power Units repacks batteries for cordless appliances such as power tools, radios and shavers, using higher-capacity 2,200 mA/h cells that last longer between charges than most original batteries. The business also stocks a wide range of power supply products including inverters, charge controllers, chargers, converters, gel and alkaline batteries, and surge protection, positioned as a one-stop power solution shop for both new installations and keeping existing battery-powered equipment running.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.sppowerunits.co.za/'), description_enriched_at = datetime('now') WHERE slug = 's-and-p-power-units-wonderboom' AND description = 'S and P Power Units is a renewable-energy and power-supply company with over 30 years of experience, designing, supplying and installing off-grid and grid-tied solar systems and backup power solutions for commercial, residential and agricultural clients. The business also offers battery repacking for cordless appliances and power tools, and stocks solar panels, inverters and batteries from brands including Victron, Varta and Trina Solar.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
