-- woodhill-country-club-woodhill-golf-estate (researched)
UPDATE businesses SET description = 'Woodhill Country Club''s golf course sits on a former dairy farm in the south-eastern suburbs of Pretoria, designed by Peter Matkovich and built to retain the site''s old pastoral charm even as the residential estate around it grew up. The parklands layout plays over Kikuyu fairways and bent-grass greens across a front nine that rises and circles ''the hill'' before flattening into a more heavily wooded back nine, running to a total length of 6,752 metres with a choice of three tee options.

The course hosted the PGA Championship in 2001, a measure of its standing among South African parkland courses, and its facilities include a clubhouse, driving range, pro shop, teaching academy and locker rooms. Visitors are welcome at Woodhill Country Club, though not on Saturday mornings, and the club advises booking tee times and any nearby accommodation ahead to avoid disappointment during busier periods.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.sa-venues.com/golf/woodhill-golf-course.php'), description_enriched_at = datetime('now') WHERE slug = 'woodhill-country-club-woodhill-golf-estate' AND description = 'Woodhill Country Club is an 18-hole, par-72 golf course and clubhouse in Woodhill Golf Estate, built on a former dairy farm and opened in 1999. The parkland layout plays over undulating, tree-lined fairways with a mix of kikuyu and bent grass, and the course hosted the South African PGA Championship in 2001. On-site facilities include a driving range, pro shop, teaching academy, locker rooms, and a clubhouse restaurant and bar with panoramic terraces overlooking the course.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
